import logging

from taf.fdsw.rc.interfaces.FDSW19.diagnostics import Diagnostics19

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())
logging.basicConfig(level=logging.INFO)


class Diagnostics20B(Diagnostics19):

    def download_autoconfiguration_report(self, path, timeout):
        endpoint = 'diagnostics.pnp.download'
        return self._client.get_diagnostics(endpoint, path, timeout)

    def download_technical_logs(self, zip_path, timeout):
        self._start_collecting(timeout)
        logger.info('Collecting log files ...')

        self._client.download_files(zip_path=zip_path, timeout=timeout)
        logger.info('Files collected')
